<template><div class="page"><v-card flat class="hero pa-5 mb-4"><div class="d-flex align-center flex-wrap"><div><div class="text-overline">SALES & FINANCE</div><h1 class="text-h5 font-weight-bold">Installment Plans</h1><div class="grey--text">Create and manage booking payment schedules.</div></div><v-spacer/><v-btn v-if="$can('installments.create')" color="#165134" dark depressed class="rounded-lg" @click="openCreate"><v-icon left>mdi-calendar-plus</v-icon>New Plan</v-btn></div></v-card><v-row class="mb-1"><v-col cols="6" md="3"><v-card flat class="summary-card pa-4"><div class="caption grey--text">Plans Shown</div><div class="text-h6 font-weight-bold">{{items.length}}</div></v-card></v-col><v-col cols="6" md="3"><v-card flat class="summary-card pa-4"><div class="caption grey--text">Active</div><div class="text-h6 font-weight-bold success--text">{{activeCount}}</div></v-card></v-col><v-col cols="6" md="3"><v-card flat class="summary-card pa-4"><div class="caption grey--text">Completed</div><div class="text-h6 font-weight-bold primary--text">{{completedCount}}</div></v-card></v-col><v-col cols="6" md="3"><v-card flat class="summary-card pa-4"><div class="caption grey--text">Planned Amount Shown</div><div class="text-h6 font-weight-bold">PKR {{money(plannedShown)}}</div></v-card></v-col></v-row><v-card flat class="filter-card mb-4"><v-card-text><v-select v-model="status" :items="statuses" clearable outlined dense label="Status" @change="load"/></v-card-text></v-card><v-card flat class="table-card"><v-data-table :headers="headers" :items="items" :loading="loading" :options.sync="options" :server-items-length="total"><template v-slot:item.total_amount="{item}">PKR {{money(item.total_amount)}}</template><template v-slot:item.status="{item}"><v-chip x-small :color="item.status==='active'?'success':item.status==='completed'?'primary':'grey'" dark>{{item.status}}</v-chip></template><template v-slot:item.actions="{item}"><v-btn v-if="$can('installments.view')" icon small @click="view(item)"><v-icon small>mdi-eye</v-icon></v-btn><v-btn v-if="$can('installments.edit')" icon small @click="edit(item)"><v-icon small>mdi-pencil</v-icon></v-btn><v-btn v-if="$can('installments.delete')" icon small color="error" @click="openDelete(item)"><v-icon small>mdi-delete</v-icon></v-btn></template></v-data-table></v-card><v-dialog v-model="dialog" max-width="760" persistent><v-card><v-card-title>{{editing?'Update Installment Plan':'New Installment Plan'}}<v-spacer/><v-btn icon :disabled="saving" @click="dialog=false"><v-icon>mdi-close</v-icon></v-btn></v-card-title><v-card-text><v-row><v-col v-if="!editing" cols="12"><v-autocomplete v-model="form.booking_id" :items="bookings" item-value="id" :item-text="bookingLabel" outlined dense label="Booking *" :loading="loadingBookings" @change="bookingChanged"/></v-col><v-col v-if="!editing && selectedBooking" cols="12"><v-alert type="info" text dense>Outstanding booking balance: <strong>PKR {{money(selectedBooking.remaining_amount)}}</strong>. The plan total cannot exceed the unallocated outstanding balance.</v-alert></v-col><v-col cols="12" md="6"><v-text-field v-model="form.plan_name" outlined dense label="Plan Name *"/></v-col><v-col v-if="editing" cols="12" md="6"><v-select v-model="form.status" :items="statuses" outlined dense label="Status *"/></v-col><template v-if="!editing"><v-col cols="12" md="6"><v-select v-model="form.frequency" :items="frequencies" item-text="text" item-value="value" outlined dense label="Frequency *"/></v-col><v-col cols="12" md="4"><v-text-field v-model="form.total_amount" type="number" min="0.01" outlined dense label="Plan Total *"/></v-col><v-col cols="12" md="4"><v-text-field v-model="form.installment_amount" type="number" min="0.01" outlined dense label="Installment Amount *" hint="Calculated from total ÷ installments" persistent-hint/></v-col><v-col cols="12" md="4"><v-text-field v-model="form.number_of_installments" type="number" min="1" outlined dense label="No. of Installments *" @input="calculateInstallmentAmount"/></v-col><v-col cols="12"><v-alert v-if="scheduleDifference" type="warning" text dense>Schedule total differs by PKR {{ money(Math.abs(scheduleDifference)) }}. Installment amount must make the schedule equal the plan total.</v-alert></v-col><v-col cols="12" md="6"><v-text-field v-model="form.start_date" type="date" outlined dense label="Start Date *"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.end_date" type="date" outlined dense label="End Date"/></v-col></template><v-col cols="12"><v-textarea v-model="form.notes" outlined dense rows="2" label="Notes"/></v-col></v-row></v-card-text><v-card-actions><v-spacer/><v-btn text :disabled="saving" @click="dialog=false">Cancel</v-btn><v-btn color="#165134" dark :loading="saving" @click="save">Save Plan</v-btn></v-card-actions></v-card></v-dialog><v-dialog v-model="detailsDialog" max-width="850"><v-card v-if="selected"><v-card-title>{{selected.plan_name}}<v-spacer/><v-btn icon @click="detailsDialog=false"><v-icon>mdi-close</v-icon></v-btn></v-card-title><v-card-text><div class="mb-4">{{selected.booking&&selected.booking.booking_number}} · {{selected.frequency}} · PKR {{money(selected.total_amount)}}</div><v-data-table dense :headers="installmentHeaders" :items="selected.installments||[]" :items-per-page="20"><template v-slot:item.amount="{item}">PKR {{money(item.amount)}}</template><template v-slot:item.remaining_amount="{item}">PKR {{money(item.remaining_amount)}}</template></v-data-table></v-card-text></v-card></v-dialog><v-dialog v-model="deleteDialog" max-width="500" persistent><v-card><v-card-title>Delete Installment Plan</v-card-title><v-card-text><v-alert type="warning" outlined dense>Delete <strong>{{deleteItem&&deleteItem.plan_name}}</strong>? Plans with payment history cannot be deleted.</v-alert></v-card-text><v-card-actions><v-spacer/><v-btn text :disabled="deleting" @click="deleteDialog=false">Cancel</v-btn><v-btn color="error" :loading="deleting" @click="confirmDelete">Delete Plan</v-btn></v-card-actions></v-card></v-dialog></div></template><script>import api from '../../../services/api';export default{name:'InstallmentPlans',data(){return{loading:false,saving:false,deleting:false,dialog:false,detailsDialog:false,deleteDialog:false,editing:null,selected:null,deleteItem:null,status:null,items:[],total:0,bookings:[],loadingBookings:false,options:{page:1,itemsPerPage:15},statuses:['active','completed','cancelled'],frequencies:[{text:'Monthly',value:'monthly'},{text:'Quarterly',value:'quarterly'},{text:'Half Yearly',value:'half_yearly'},{text:'Yearly',value:'yearly'}],headers:[{text:'Plan',value:'plan_name'},{text:'Booking',value:'booking.booking_number'},{text:'Customer',value:'booking.customer.name'},{text:'Frequency',value:'frequency'},{text:'Total',value:'total_amount'},{text:'Installments',value:'number_of_installments'},{text:'Status',value:'status'},{text:'Actions',value:'actions',sortable:false}],installmentHeaders:[{text:'#',value:'installment_number'},{text:'Due Date',value:'due_date'},{text:'Amount',value:'amount'},{text:'Paid',value:'paid_amount'},{text:'Remaining',value:'remaining_amount'},{text:'Status',value:'status'}],form:this.blank()}},computed:{selectedBooking(){return this.bookings.find(function(b){return Number(b.id)===Number(this.form.booking_id)},this)||null},activeCount(){return this.items.filter(function(x){return x.status==='active'}).length},completedCount(){return this.items.filter(function(x){return x.status==='completed'}).length},plannedShown(){return this.items.reduce(function(n,x){return n+Number(x.total_amount||0)},0)}},watch:{options:{deep:true,handler(){this.load()}},'form.total_amount':function(){if(!this.editing)this.calculateInstallmentAmount()}},mounted(){this.load();if(this.$route.query.booking_id)this.openCreateFromQuery()},methods:{blank(){return{booking_id:null,plan_name:'',frequency:'monthly',total_amount:null,down_payment:0,installment_amount:null,number_of_installments:1,start_date:new Date().toISOString().slice(0,10),end_date:null,status:'active',notes:''}},scheduleDifference(){const total=Number(this.form.total_amount||0),amount=Number(this.form.installment_amount||0),count=Number(this.form.number_of_installments||0);return Math.round((amount*count-total)*100)/100},calculateInstallmentAmount(){const total=Number(this.form.total_amount||0),count=parseInt(this.form.number_of_installments||0,10);if(total>0&&count>0)this.form.installment_amount=(Math.round((total/count)*100)/100).toFixed(2)},bookingLabel(b){return b.booking_number+' — '+(b.customer?b.customer.name:'Customer')+' — Balance PKR '+this.money(b.remaining_amount)},async load(){this.loading=true;try{const r=await api.get('/installment-plans',{params:{status:this.status,page:this.options.page,per_page:this.options.itemsPerPage}});this.items=r.data.data||[];this.total=r.data.total||0}catch(e){this.$root.$emit('show-error',(e.response&&e.response.data&&e.response.data.message)||'Unable to load installment plans.')}finally{this.loading=false}},async loadBookings(){this.loadingBookings=true;try{const r=await api.get('/bookings',{params:{per_page:100}});this.bookings=(r.data.data||[]).filter(b=>!['cancelled','completed'].includes(b.status)&&Number(b.remaining_amount)>0)}finally{this.loadingBookings=false}},async openCreate(){this.editing=null;this.form=this.blank();this.dialog=true;await this.loadBookings()},async openCreateFromQuery(){await this.openCreate();const id=Number(this.$route.query.booking_id||0);const booking=this.bookings.find(function(b){return Number(b.id)===id});if(booking){this.form.booking_id=booking.id;this.form.plan_name='Payment Plan - '+booking.booking_number;this.form.total_amount=Number(booking.remaining_amount||0);this.calculateInstallmentAmount()}},bookingChanged(id){const booking=this.bookings.find(function(b){return Number(b.id)===Number(id)});if(booking){this.form.total_amount=Number(booking.remaining_amount||0);if(!this.form.plan_name)this.form.plan_name='Payment Plan - '+booking.booking_number;this.calculateInstallmentAmount()}},edit(i){this.editing=i;this.form={plan_name:i.plan_name,status:i.status,notes:i.notes||''};this.dialog=true},async save(){if(!this.form.plan_name){this.$root.$emit('show-error','Plan name is required.');return}if(!this.editing&&(!this.form.booking_id||!this.form.total_amount||!this.form.installment_amount||!this.form.number_of_installments)){this.$root.$emit('show-error','Booking and installment schedule fields are required.');return}if(!this.editing&&Math.abs(this.scheduleDifference)>0.01){this.$root.$emit('show-error','Installment amount × number of installments must equal the plan total.');return}this.saving=true;try{if(this.editing)await api.put('/installment-plans/'+this.editing.id,this.form);else await api.post('/installment-plans',this.form);this.dialog=false;await this.load();this.$root.$emit('show-success','Installment plan saved successfully.')}catch(e){this.$root.$emit('show-error',(e.response&&e.response.data&&e.response.data.message)||'Unable to save installment plan.')}finally{this.saving=false}},async view(i){try{const r=await api.get('/installment-plans/'+i.id);this.selected=r.data;this.detailsDialog=true}catch(e){this.$root.$emit('show-error','Unable to load installment plan.')}},openDelete(i){this.deleteItem=i;this.deleteDialog=true},async confirmDelete(){if(!this.deleteItem)return;this.deleting=true;try{await api.delete('/installment-plans/'+this.deleteItem.id);this.deleteDialog=false;this.deleteItem=null;await this.load();this.$root.$emit('show-success','Installment plan deleted successfully.')}catch(e){this.$root.$emit('show-error',(e.response&&e.response.data&&e.response.data.message)||'Unable to delete installment plan.')}finally{this.deleting=false}},money(v){return new Intl.NumberFormat('en-PK',{maximumFractionDigits:0}).format(Number(v||0))}}}</script><style scoped>.page{width:100%}.hero{border-left:4px solid #165134}.summary-card,.filter-card,.table-card{border:1px solid rgba(22,81,52,.08);border-radius:15px!important}.page ::v-deep .v-data-table__wrapper{overflow-x:auto}</style>